<script setup lang="ts">
import { computed } from 'vue';
import { showDateTime } from '../utils/time';
import type { WarehousePallet } from '../types/warehouse';
const props=withDefaults(defineProps<{pallet:WarehousePallet;authenticated:boolean;busy:boolean;interactive?:boolean}>(),{interactive:true});
const emit=defineEmits<{detail:[];history:[];edit:[];remove:[]}>();
const pending=computed(()=>props.pallet.items.some(item=>item.quantity==null));
</script>
<template>
  <article class="pallet-card card" :class="{clickable:interactive!==false}">
    <button v-if="interactive!==false" class="card-detail" :aria-label="`查看托盘 ${pallet.code} 详情`" @click="emit('detail')"/>
    <header><strong class="location-tag">{{pallet.location}}</strong><span class="status" :class="pending?'neutral':'ok'">{{pending?'待盘点':'已盘点'}}</span></header>
    <p class="pallet-code"><span>托盘 <span class="mono" translate="no">{{pallet.code}}</span></span><span>{{pallet.items.length}} 项物料</span></p>
    <div class="material-list">
      <section v-for="(item,index) in pallet.items" :key="index" class="stored-item">
        <a v-if="item.photoUrl" :href="item.photoUrl" target="_blank" rel="noopener" class="stock-photo" :aria-label="`查看${item.productName}照片（新窗口）`"><img :src="item.photoUrl" :alt="`${item.productName}照片`" width="56" height="56" loading="lazy"></a>
        <div class="material-content">
          <div class="material-heading"><h3>{{item.productName}} <small v-if="item.finished" class="finished-tag">成品</small></h3><div class="item-quantity"><strong v-if="item.quantity!=null">{{item.quantity.toLocaleString()}} <small>{{item.unit}}</small></strong><span v-else class="unknown-quantity">数量未确认</span><span v-if="item.cartons!=null" class="cartons">{{item.cartons.toLocaleString()}} 箱<span v-if="item.unitsPerCarton"> · {{item.unitsPerCarton.toLocaleString()}} {{item.unit}}/箱</span></span><span v-if="item.boxesPerCarton&&item.unitsPerBox" class="cartons">{{item.boxesPerCarton}} 盒/箱 × {{item.unitsPerBox}} {{item.unit}}/盒</span></div></div>
          <div class="item-identity"><span v-if="item.materialCode">编码 <span class="mono">{{item.materialCode}}</span></span><span>原料批号 <span class="mono">{{item.rawMaterialBatch||'未录入'}}</span></span><span>批号 <span class="mono">{{item.batch||'未录入'}}</span></span></div>
        </div>
      </section>
    </div>
    <p v-if="pallet.notes" class="pallet-notes">备注：{{pallet.notes}}</p>
    <footer><time :datetime="pallet.updatedAt">更新 {{showDateTime(pallet.updatedAt)}}</time><div class="card-actions"><button class="text-button" @click="emit('history')">操作历史</button><button v-if="authenticated" class="text-button edit-button" :disabled="busy" @click="emit('edit')">编辑 / 移位</button><details v-if="authenticated" class="more-actions"><summary :aria-label="`${pallet.code} 的更多操作`">更多</summary><div><button class="text-button danger" :disabled="busy" @click="($event.currentTarget as HTMLElement).closest('details')?.removeAttribute('open');emit('remove')">移除托盘</button></div></details></div></footer>
  </article>
</template>
